if (cacheParams.prefetch.isEmpty) {
val aControl = Cat(io.in.a.bits.opcode, io.in.a.bits.param, io.in.a.bits.size, io.in.a.bits.source, io.in.a.bits.address, io.in.a.bits.mask)
val cControl = Cat(io.in.c.bits.opcode, io.in.c.bits.param, io.in.c.bits.size, io.in.c.bits.source, io.in.c.bits.address)
val dControl = Cat(io.in.d.bits.opcode, io.in.d.bits.param, io.in.d.bits.size, io.in.d.bits.source, io.in.d.bits.sink, io.in.d.bits.denied, io.in.d.bits.corrupt)
val (aFirst, aLast, _, _) = edgeIn.count(io.in.a)
val (cFirst, cLast, _, _) = edgeIn.count(io.in.c)
val (dFirst, dLast, _, _) = edgeIn.count(io.in.d)
val aActive = RegInit(false.B)
val cActive = RegInit(false.B)
val dActive = RegInit(false.B)
val aReference = Reg(chiselTypeOf(aControl))
val cReference = Reg(chiselTypeOf(cControl))
val dReference = Reg(chiselTypeOf(dControl))
when(io.in.a.fire && aFirst && !aLast) { aActive := true.B; aReference := aControl }
when(io.in.c.fire && cFirst && !cLast) { cActive := true.B; cReference := cControl }
when(io.in.d.fire && dFirst && !dLast) { dActive := true.B; dReference := dControl }
when(io.in.a.fire && aLast) { aActive := false.B }
when(io.in.c.fire && cLast) { cActive := false.B }
when(io.in.d.fire && dLast) { dActive := false.B }
val aBurstControlViolation = aActive && io.in.a.valid && aControl =/= aReference
val cBurstControlViolation = cActive && io.in.c.valid && cControl =/= cReference
val dBurstControlViolation = dActive && io.in.d.valid && dControl =/= dReference
chisel3.util.experimental.BoringUtils.addSource(aBurstControlViolation, s"${cacheParams.name}_{{source_label}}_burst_a", disableDedup = true)
chisel3.util.experimental.BoringUtils.addSource(cBurstControlViolation, s"${cacheParams.name}_{{source_label}}_burst_c", disableDedup = true)
chisel3.util.experimental.BoringUtils.addSource(dBurstControlViolation, s"${cacheParams.name}_{{source_label}}_burst_d", disableDedup = true)
}
